    case "passed": {
      // `terminal_status: passed` means the reviewer posted APPROVE. It does NOT
      // mean the implementation PR is merged. The reviewer may attempt the merge
      // in Step 7 of review-pr/SKILL.md, but the merge may be skipped
      // (`execution.requires_human_review === true`) or rejected (branch
      // protection requires a human approval). Either way, the task stays
      // `in_review` here; the in_review PR poll detects merged=true on GitHub
      // and handleMergedPrs writes the done state at that point.
      if (result.self_review_skipped) {
        emit({ type: "reviewer_self_review_skipped", task_id: taskId, feature_id: featureId,
               pr_number: prNumber });
      }
      emit({ type: "review_passed", task_id: taskId, feature_id: featureId,
             verdict: result.verdict, confidence: result.confidence, notes: result.notes, review_url: result.review_url });
      break;
    }

    case "change_requested": {
      if (result.self_review_skipped) {
        emit({ type: "reviewer_self_review_skipped", task_id: taskId, feature_id: featureId,
               pr_number: prNumber });
      }
      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot, featureId, taskId, taskBranch,
        status: "change_requested",
        logEntry: {
          action: "reviewer_complete",
          by: gitAuthorEmail,
          note: result.notes ?? "Reviewer requested changes.",
          // Persist the specific review URL so the fix agent can fetch exactly
          // this review's inline comments (precise) instead of "all unresolved
          // threads on the PR" (lossy across multiple review cycles).
          ...(result.review_url ? { review_url: result.review_url } : {}),
        },
        gitAuthorEmail, gitAuthorName, sshKeyPath,
        commitMessage: `chore(${taskId}): reviewer → change_requested`,
      });
      if (mutateErr) {
        emit({ type: "review_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
        return;
      }
      emit({ type: "review_change_requested", task_id: taskId, feature_id: featureId,
             notes: result.notes, review_url: result.review_url });
      // Demote task PR back to draft while fixes are in progress
      if (prUrl && githubToken) {
        const prMatch = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(prUrl);
        if (prMatch) {
          const [, owner, repo, prNumber] = prMatch;
          try {
            curlJson([
              "-s", "-X", "PATCH",
              "-H", `Authorization: token ${githubToken}`,
              "-H", "Accept: application/vnd.github+json",
              "-H", "Content-Type: application/json",
              "-d", JSON.stringify({ draft: true }),
              `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
            ]);
          } catch (e) {
            emit({ type: "task_pr_demote_failed", task_id: taskId, feature_id: featureId, details: String(e) });
          }
        }
      }
      break;
    }

    case "escalate":
      await handleEscalation({
        workspaceRoot, featureId, taskId,
        taskTitle, prUrl,
        notes: result.notes,
        reviewUrl: result.review_url,
        gitAuthorEmail, gitAuthorName, sshKeyPath,
        notifier,
        emit,
      });
      break;

    default: {
      // Reviewer exited without writing a valid result (e.g. max-turns during CI polling).
      // Mirror the impl executor's max-turns retry: write a review_blocked log entry and
      // leave the task in_review. The claim guard (last log action ≠ reviewer_started)
      // lets the next poll cycle re-dispatch the reviewer automatically.
      // After MAX_REVIEW_INCOMPLETES attempts, escalate instead of retrying.
      const maxIncompletes = parseInt(process.env["MAX_REVIEW_INCOMPLETES"] ?? "2", 10);

      let reviewBlockedCount = 0;
      try {
        const currentTask = readTask(workspaceRoot, featureId, taskId);
        reviewBlockedCount = currentTask.log.filter((e) => e.action === "review_blocked").length;
      } catch { /* non-fatal — treat as 0 */ }

      emit({
        type: "review_incomplete",
        task_id: taskId, feature_id: featureId,
        terminal_status: (result as { terminal_status: string }).terminal_status,
        review_blocked_count: reviewBlockedCount,
        max_incompletes: maxIncompletes,
      });

      if (reviewBlockedCount >= maxIncompletes) {
        await handleEscalation({
          workspaceRoot, featureId, taskId,
          taskTitle, prUrl,
          notes: `Reviewer exited without completing ${reviewBlockedCount + 1} times — escalating after ${maxIncompletes} retries.`,
          gitAuthorEmail, gitAuthorName, sshKeyPath,
          notifier,
          emit,
        });
        return;
      }

      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot, featureId, taskId, taskBranch,
        status: "review_incomplete",
        logEntry: {
          action: "review_blocked",
          by: gitAuthorEmail,
          note: `Reviewer exited without result (attempt ${reviewBlockedCount + 1} of ${maxIncompletes}). Will retry next cycle.`,
        },
        gitAuthorEmail, gitAuthorName, sshKeyPath,
        commitMessage: `chore(${taskId}): review_blocked — incomplete attempt ${reviewBlockedCount + 1}`,
      });

      if (mutateErr) {
        emit({ type: "review_blocked_write_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
      } else {
        emit({ type: "review_blocked_logged", task_id: taskId, feature_id: featureId,
               attempt: reviewBlockedCount + 1, max_incompletes: maxIncompletes });
