// ── 10. in_review with pr_url, PATCH fails → task_pr_promote_failed ──────────

describe("seam: in_review with pr_url — PATCH failure emits task_pr_promote_failed", () => {
  it("emits task_pr_promote_failed when curl PATCH errors; task is still in_review", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        // Network-level failure: empty stdout, non-zero status
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (6) Could not resolve host", status: 1, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(true);
    // PATCH failure is non-fatal — task still transitions to in_review
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });

  it("emits task_pr_promote_failed when GitHub returns HTTP 403/422 (--fail exits 22)", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        // --fail causes curl to exit 22 on HTTP 4xx; body is suppressed
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (22) The requested URL returned error: 403",
          status: 22, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(true);
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });
});

// ── 11. in_review with WIP pr_url → title cleaned up ────────────────────────

describe("seam: in_review with [WIP] PR title — cleans up title and body", () => {
  it("PATCHes PR title/body and emits task_pr_title_updated when title starts with [WIP]", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const patchedBodies: string[] = [];
    let callCount = 0;
    vi.mocked(spawnSync).mockImplementation((cmd, args) => {
      if (cmd === "curl") {
        callCount++;
        if (callCount === 1) {
          // REST GET — return node_id + WIP title
          return {
            pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
            stdout: JSON.stringify({
              html_url: IMPL_PR_URL,
              number: 99,
              node_id: "PR_nodeid_abc123",
              title: `[WIP] feat(${FEATURE_ID}/${TASK_ID}): agent terminated — draft PR`,
            }),
          } as unknown as ReturnType<typeof spawnSync>;
        }
        if (callCount === 2) {
          // GraphQL markPullRequestReadyForReview
          return {
            pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
            stdout: JSON.stringify({ data: { markPullRequestReadyForReview: { pullRequest: { isDraft: false } } } }),
          } as unknown as ReturnType<typeof spawnSync>;
        }
        // callCount === 3: REST PATCH to update title/body
        const argList = args as string[];
        const dIdx = argList.indexOf("-d");
        if (dIdx !== -1) patchedBodies.push(argList[dIdx + 1] as string);
        return {
          pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
          stdout: JSON.stringify({ html_url: IMPL_PR_URL, number: 99 }),
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    // Three curl calls: GET, GraphQL, PATCH
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(3);

    // Third call is REST PATCH to the pulls endpoint
    const patchArgs = curlCalls[2][1] as string[];
    expect(patchArgs).toContain("-X");
    expect(patchArgs).toContain("PATCH");
    expect(patchArgs.some((a) => typeof a === "string" && a.includes("/pulls/99"))).toBe(true);

    // Patched title no longer has [WIP] prefix
    expect(patchedBodies.length).toBe(1);
    const patched = JSON.parse(patchedBodies[0]) as { title: string; body: string };
    expect(patched.title).not.toMatch(/^\[WIP\]/);
    expect(patched.title).toBe(`feat(${FEATURE_ID}/${TASK_ID}): ${TASK_TITLE}`);

    // Event emitted
    expect(events.some((e) => e.type === "task_pr_title_updated")).toBe(true);
    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(false);

    // Task still transitions normally
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });

  it("does not PATCH when title does not start with [WIP]", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        return {
          pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
          stdout: JSON.stringify({
            html_url: IMPL_PR_URL,
            number: 99,
            node_id: "PR_nodeid_abc123",
            title: `feat(${FEATURE_ID}/${TASK_ID}): proper title`,
          }),
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    // Only two curl calls: GET + GraphQL — no PATCH
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
