// ── 12. in_review with WIP pr_url, PATCH fails → task_pr_title_update_failed ─

describe("seam: in_review with [WIP] PR title — PATCH failure emits task_pr_title_update_failed", () => {
  it("emits task_pr_title_update_failed when PATCH fails; task still in_review, promote not failed", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    let callCount = 0;
    vi.mocked(spawnSync).mockImplementation((cmd) => {
      if (cmd === "curl") {
        callCount++;
        if (callCount === 1) {
          // REST GET — return node_id + WIP title
          return {
            pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
            stdout: JSON.stringify({
              html_url: IMPL_PR_URL,
              number: 99,
              node_id: "PR_nodeid_abc123",
              title: `[WIP] feat(${FEATURE_ID}/${TASK_ID}): agent terminated — draft PR`,
            }),
          } as unknown as ReturnType<typeof spawnSync>;
        }
        if (callCount === 2) {
          // GraphQL markPullRequestReadyForReview — succeeds
          return {
            pid: 0, output: [], stderr: "", status: 0, signal: null, error: undefined,
            stdout: JSON.stringify({ data: { markPullRequestReadyForReview: { pullRequest: { isDraft: false } } } }),
          } as unknown as ReturnType<typeof spawnSync>;
        }
        // callCount === 3: REST PATCH — fails (HTTP 422 via --fail → exit 22)
        return {
          pid: 0, output: [], stdout: "",
          stderr: "curl: (22) The requested URL returned error: 422",
          status: 22, signal: null, error: undefined,
        } as unknown as ReturnType<typeof spawnSync>;
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    // Three curl calls attempted: GET, GraphQL, PATCH
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(3);

    // Title update failure is reported with its own event — not as a promote failure
    expect(events.some((e) => e.type === "task_pr_title_update_failed")).toBe(true);
    expect(events.some((e) => e.type === "task_pr_title_updated")).toBe(false);
    expect(events.some((e) => e.type === "task_pr_promote_failed")).toBe(false);

    // PATCH failure is non-fatal — task still transitions to in_review
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
  });
});

