interface NotifierCall { trigger: TaskTrigger; context: TaskContext }

function makeNotifier(): { notifier: NotificationPort; calls: NotifierCall[] } {
  const calls: NotifierCall[] = [];
  const notifier: NotificationPort = {
    postTaskMessage: async (_fid, _tid, trigger, context) => { calls.push({ trigger, context }); },
    closeTaskThread: async () => {},
    postFeatureMessage: async () => {},
    closeFeatureThread: async () => {},
  };
  return { notifier, calls };
}

