/**
 * Tests for poll/reap-loop.ts
 *
 * Covers:
 *   1. Empty queue: returns { dispatched: 0, failed: 0 }, no side effects.
 *   2. kind=impl: calls dispatchExecutorResult and acks.
 *   3. kind=review-fix: emits review_dispatch_complete and acks.
 *   4. Workspace not found: nacks and increments failed count.
 *   5. Dispatch error: nacks and increments failed count.
 *   6. Mixed completions: dispatches each by kind independently.
 *   7. E2E: submit → fake callback → runReapLoop → task YAML mutated to in_review.
 *   8. Task YAML on branch only (not on local FS): findWorkspaceRoot + readTaskAny branch fallback.
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import { execSync, spawnSync } from "node:child_process";
import type { SpawnSyncReturns } from "node:child_process";

import { FakeBrokerAdapter } from "@workflow/runtime-abi";
import { runReapLoop } from "../src/poll/reap-loop.js";
import type { Task } from "../src/types/task.js";

// ── Mock git calls made by dispatchExecutorResult ─────────────────────────────
vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "reap-test-feature";
const TASK_ID = "T1";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const TASK_TITLE = "Reap test task";
const TASK_REPO = "impl-repo";
const GIT_AUTHOR_EMAIL = "agent@reap-test.com";
const GITHUB_TOKEN = "ghp_test";

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: TASK_TITLE,
    repo: TASK_REPO,
    status: "in_progress",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

/**
 * Create a workspace directory with a minimal workspace.yaml but WITHOUT any
 * task YAML on the local FS. Used to test the branch-fallback paths in
 * findWorkspaceRoot and readTaskAny.
 */
function makeWorkspaceWithoutTask(): string {
  const wsRoot = makeTmpDir("reap-ws-notask-");
  // Create the tasks directory so dispatchExecutorResult can write the task YAML back,
  // but do NOT write the task YAML itself — that's what we're testing the branch fallback for.
  mkdirSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks"), { recursive: true });
  const wsYaml = {
    workspace_id: "test-ws",
    repos: [
      {
        id: TASK_REPO,
        github: "git@github.com:org/impl-repo.git",
        local_path: "/tmp/impl-repo",
        base_branch: "main",
      },
    ],
  };
  writeFileSync(join(wsRoot, "workspace.yaml"), yamlStringify(wsYaml), "utf-8");
  return wsRoot;
}

/**
 * Create a workspace directory with a task YAML and a minimal workspace.yaml.
 * Returns the workspace root path.
 */
function makeWorkspaceWithTask(task: Task): string {
  const wsRoot = makeTmpDir("reap-ws-");
  const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");

  // Minimal workspace.yaml so resolveRepoGitUrl / resolveRepoBaseBranch work
  const wsYaml = {
    workspace_id: "test-ws",
    repos: [
      {
        id: TASK_REPO,
        github: "git@github.com:org/impl-repo.git",
        local_path: "/tmp/impl-repo",
        base_branch: "main",
      },
    ],
  };
  writeFileSync(join(wsRoot, "workspace.yaml"), yamlStringify(wsYaml), "utf-8");

  return wsRoot;
}

function readTask(wsRoot: string): Task {
  return parseYaml(
    readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
  ) as Task;
}

function mockGitSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

// ── 1. Empty queue ────────────────────────────────────────────────────────────

describe("runReapLoop — empty queue", () => {
  it("returns zero counts when broker has no completions", async () => {
    const broker = new FakeBrokerAdapter();
    const events: Record<string, unknown>[] = [];

    const result = await runReapLoop({
      broker,
      workspaceRoots: [],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 0, failed: 0 });
    expect(events).toHaveLength(0);
  });
});

// ── 2. kind=impl: dispatch + ack ──────────────────────────────────────────────

describe("runReapLoop — kind=impl", () => {
  it("calls dispatchExecutorResult and acks the handle", async () => {
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const wsRoot = makeWorkspaceWithTask(makeTask());
    const broker = new FakeBrokerAdapter();
    const handle = "handle-impl-001";
    const nonce = "nonce-impl-001";

    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({
      handle,
      nonce,
      result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" },
    });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 1, failed: 0 });
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    // executor_result event emitted
    const execResultEvent = events.find((e) => e.type === "executor_result");
    expect(execResultEvent).toBeDefined();
    expect(execResultEvent!.terminal_status).toBe("in_review");

    // reap_acked event emitted
    const ackedEvent = events.find((e) => e.type === "reap_acked");
    expect(ackedEvent).toBeDefined();
    expect(ackedEvent!.handle).toBe(handle);
    expect(ackedEvent!.kind).toBe("impl");

    // task YAML updated
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
  });
});

// ── 3. kind=review-fix ────────────────────────────────────────────────────────

describe("runReapLoop — kind=review-fix", () => {
  it("emits review_dispatch_complete and acks (no task YAML mutation)", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask({ status: "in_review" }));
    const broker = new FakeBrokerAdapter();
    const handle = "handle-rf-001";
    const nonce = "nonce-rf-001";

    await broker.register(handle, nonce, {
      kind: "review-fix",
      subkind: "respond",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({
      handle,
      nonce,
      result: { terminal_status: "in_review" },
    });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 1, failed: 0 });
    expect(broker.queueDepth()).toBe(0);

    const rfEvent = events.find((e) => e.type === "review_dispatch_complete");
    expect(rfEvent).toBeDefined();
    expect(rfEvent!.task_id).toBe(TASK_ID);
    expect(rfEvent!.subkind).toBe("respond");
    expect(rfEvent!.outcome).toBe("in_review");

    // task YAML status unchanged (no mutation for review-fix)
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
  });
});

// ── 4. Workspace not found ────────────────────────────────────────────────────

describe("runReapLoop — workspace not found", () => {
  it("nacks and counts as failed when no workspace contains the task", async () => {
    const broker = new FakeBrokerAdapter();
    const handle = "handle-lost-001";
    const nonce = "nonce-lost-001";

    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: "T99",
      feature_id: "no-such-feature",
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle, nonce, result: { terminal_status: "in_review" } });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: ["/nonexistent/path"],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 0, failed: 1 });
    const notFoundEvent = events.find((e) => e.type === "reap_workspace_not_found");
    expect(notFoundEvent).toBeDefined();
    expect(notFoundEvent!.handle).toBe(handle);
    // Item is nacked (unlocked, stays in queue for retry)
    expect(broker.queueDepth()).toBe(1);
    broker.reclaimExpired();
    const retry = await broker.listCompleted({ max: 1 });
    expect(retry).toHaveLength(1);
  });
});

// ── 5. Dispatch error → nack ──────────────────────────────────────────────────

describe("runReapLoop — dispatch error", () => {
  it("nacks and counts as failed when dispatch throws", async () => {
    // Trigger a real exception by omitting the task's repo from workspace.yaml.
    // resolveRepoGitUrl() throws before dispatchExecutorResult is called, which
    // propagates to runReapLoop's catch block → nack + failed++.
    const wsRoot = makeTmpDir("reap-err-ws-");
    const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
    mkdirSync(tasksDir, { recursive: true });
    const task = makeTask();
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
    // workspace.yaml with no repos → resolveRepoGitUrl("impl-repo") throws
    writeFileSync(join(wsRoot, "workspace.yaml"), yamlStringify({ workspace_id: "test-ws", repos: [] }), "utf-8");

    const broker = new FakeBrokerAdapter();
    const handle = "handle-err-001";
    const nonce = "nonce-err-001";

    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle, nonce, result: { terminal_status: "in_review" } });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result.failed).toBe(1);
    expect(result.dispatched).toBe(0);

    const errEvent = events.find((e) => e.type === "reap_dispatch_error");
    expect(errEvent).toBeDefined();
    expect(String(errEvent!.details)).toContain(TASK_REPO);
    // Item nacked (remains in queue unlocked)
    broker.reclaimExpired();
    const retry = await broker.listCompleted({ max: 1 });
    expect(retry).toHaveLength(1);
  });
});

// ── 6. Mixed completions ──────────────────────────────────────────────────────

describe("runReapLoop — mixed completions", () => {
  it("handles impl and review-fix completions in the same drain", async () => {
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const wsRoot = makeWorkspaceWithTask(makeTask());
    const broker = new FakeBrokerAdapter();

    // Register impl handle
    await broker.register("h-impl", "n-impl", {
      kind: "impl", task_id: TASK_ID, feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle: "h-impl", nonce: "n-impl", result: { terminal_status: "in_review" } });

    // Register review-fix handle (same task for simplicity)
    await broker.register("h-rf", "n-rf", {
      kind: "review-fix", subkind: "rebase", task_id: TASK_ID, feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle: "h-rf", nonce: "n-rf", result: { terminal_status: "in_review" } });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result.dispatched).toBe(2);
    expect(result.failed).toBe(0);
    expect(broker.queueDepth()).toBe(0);

    expect(events.some((e) => e.type === "executor_result")).toBe(true);
    expect(events.some((e) => e.type === "review_dispatch_complete")).toBe(true);
    expect(events.filter((e) => e.type === "reap_acked")).toHaveLength(2);
  });
});

// ── 7. E2E: submit → callback → reap → dispatch ───────────────────────────────

describe("runReapLoop — E2E: claim → submit → callback → reap → dispatch → done", () => {
  it("full flow: task YAML transitions from in_progress to in_review via reap loop", async () => {
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const wsRoot = makeWorkspaceWithTask(makeTask({ status: "in_progress" }));
    const broker = new FakeBrokerAdapter();

    // Step 1: Simulate claim + submit (orchestrator submits task to executor)
    const handle = "e2e-handle-001";
    const nonce = "e2e-nonce-001";
    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });

    // Step 2: Simulate runner POSTing callback result (executor completes)
    broker.postCallback({
      handle,
      nonce,
      result: {
        terminal_status: "in_review",
        pr_url: "https://github.com/org/repo/pull/42",
      },
    });

    // Verify item is in queue before reap
    expect(broker.queueDepth()).toBe(1);

    // Step 3: Run reap loop (orchestrator drains broker completions)
    const events: Record<string, unknown>[] = [];
    const reapResult = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    // Step 4: Verify outcomes
    expect(reapResult).toEqual({ dispatched: 1, failed: 0 });

    // Broker cleaned up
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    // Task YAML reflects completion
    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe("https://github.com/org/repo/pull/42");
    expect(task.log.some((e) => e.action === "run_completed")).toBe(true);

    // Orchestrator emitted executor_result and reap_acked events
    expect(events.some((e) => e.type === "executor_result" && e.terminal_status === "in_review")).toBe(true);
    expect(events.some((e) => e.type === "reap_acked" && e.handle === handle)).toBe(true);
  });
});

// ── 9. kind=rebase: success path ─────────────────────────────────────────────
//
// Regression coverage for the bug where the rebase success path set
// conflict_state: resolved but never appended to task.log, leaving
// reviewer_started as the last entry and permanently blocking
// findReviewableTasks from dispatching review cycle 2.

describe("runReapLoop — kind=rebase (success: terminal_status=in_review)", () => {
  it("sets conflict_state: resolved and appends rebase_completed to task.log", async () => {
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const task = makeTask({ status: "in_review", conflict_state: "resolving" });
    const wsRoot = makeWorkspaceWithTask(task);
    const broker = new FakeBrokerAdapter();
    const handle = "handle-rebase-ok-001";
    const nonce = "nonce-rebase-ok-001";

    await broker.register(handle, nonce, {
      kind: "rebase",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle, nonce, result: { terminal_status: "in_review" } });

    const rebaseInFlight = new Set([`${FEATURE_ID}:${TASK_ID}`]);
    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      rebaseInFlight,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 1, failed: 0 });
    expect(broker.queueDepth()).toBe(0);

    // conflict_state written and rebase_completed appended to task.log
    const mutated = readTask(wsRoot);
    expect(mutated.conflict_state).toBe("resolved");
    const rebaseEntry = mutated.log.find((e) => e.action === "rebase_completed");
    expect(rebaseEntry).toBeDefined();
    expect(rebaseEntry!.by).toBe(GIT_AUTHOR_EMAIL);
    expect(rebaseEntry!.note).toMatch(/conflict_state resolved/);

    // in-flight key removed after ack
    expect(rebaseInFlight.has(`${FEATURE_ID}:${TASK_ID}`)).toBe(false);

    const ackedEvent = events.find((e) => e.type === "reap_acked");
    expect(ackedEvent).toBeDefined();
    expect(ackedEvent!.kind).toBe("rebase");
    expect(ackedEvent!.terminal_status).toBe("in_review");
  });

  it("does NOT append rebase_completed when rebase is blocked", async () => {
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const task = makeTask({ status: "in_review", conflict_state: "resolving" });
    const wsRoot = makeWorkspaceWithTask(task);
    const broker = new FakeBrokerAdapter();
    const handle = "handle-rebase-blocked-001";
    const nonce = "nonce-rebase-blocked-001";

    await broker.register(handle, nonce, {
      kind: "rebase",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({
      handle,
      nonce,
      result: { terminal_status: "blocked", blocked_reason: "pr_conflict" },
    });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 1, failed: 0 });

    // rebase_completed must NOT be in the log — blocked path writes a different mutation
    const mutated = readTask(wsRoot);
    expect(mutated.log.some((e) => e.action === "rebase_completed")).toBe(false);

    const ackedEvent = events.find((e) => e.type === "reap_acked");
    expect(ackedEvent).toBeDefined();
    expect(ackedEvent!.terminal_status).toBe("blocked");
  });
});

// ── 8. Branch-only task: findWorkspaceRoot + readTaskAny fallback ─────────────
//
// When a task YAML lives only on origin/<taskBranch> (e.g. it was added to the
// feature branch but never merged to main), findWorkspaceRoot must discover it
// via tryReadTaskFromBranch, and readTaskAny must read it the same way.

describe("runReapLoop — task YAML on branch only (not on local FS)", () => {
  it("dispatches correctly when task is absent from local FS but present on origin/<taskBranch>", async () => {
    const task = makeTask({ status: "in_progress" });
    const taskYaml = yamlStringify(task);

    // Mock spawnSync: return the task YAML for git-show branch calls; success for everything else.
    vi.mocked(spawnSync).mockImplementation((_cmd, args): SpawnSyncReturns<string> => {
      const argsArr = args as string[];
      if (argsArr.includes("show") && argsArr.some((a) => a.includes(TASK_BRANCH))) {
        return { pid: 0, output: [], stdout: taskYaml, stderr: "", status: 0, signal: null, error: undefined };
      }
      return { pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined };
    });

    // mutateTaskYaml does `git checkout -B <taskBranch> origin/<taskBranch>` via execSync, then
    // reads the YAML from local FS. Simulate what git checkout would actually do: materialize the
    // YAML on disk so the subsequent readFileSync succeeds.
    const wsRoot = makeWorkspaceWithoutTask();
    vi.mocked(execSync).mockImplementation((cmd: string) => {
      if (typeof cmd === "string" && cmd.includes("checkout")) {
        const yamlPath = join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`);
        writeFileSync(yamlPath, taskYaml, "utf-8");
      }
      return undefined as unknown as Buffer;
    });

    const broker = new FakeBrokerAdapter();
    const handle = "handle-branch-only-001";
    const nonce = "nonce-branch-only-001";

    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({
      handle,
      nonce,
      result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/7" },
    });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 1, failed: 0 });
    expect(broker.queueDepth()).toBe(0);

    const ackedEvent = events.find((e) => e.type === "reap_acked");
    expect(ackedEvent).toBeDefined();
    expect(ackedEvent!.handle).toBe(handle);
    expect(ackedEvent!.kind).toBe("impl");

    // git show was called at least twice: once from findWorkspaceRoot and once from readTaskAny
    const gitShowCalls = vi.mocked(spawnSync).mock.calls.filter(
      ([, a]) => (a as string[]).includes("show") && (a as string[]).some((x) => x.includes(TASK_BRANCH)),
    );
    expect(gitShowCalls.length).toBeGreaterThanOrEqual(2);
  });

  it("emits reap_workspace_not_found when task is absent from both local FS and origin/<taskBranch>", async () => {
    // All spawnSync calls (including git show branch lookups) return not-found.
    vi.mocked(spawnSync).mockReturnValue({
      pid: 0, output: [], stdout: "", stderr: "fatal: not found", status: 128, signal: null, error: undefined,
    } as unknown as ReturnType<typeof spawnSync>);

    const wsRoot = makeWorkspaceWithoutTask();
    const broker = new FakeBrokerAdapter();
    const handle = "handle-notfound-001";
    const nonce = "nonce-notfound-001";

    await broker.register(handle, nonce, {
      kind: "impl",
      task_id: TASK_ID,
      feature_id: FEATURE_ID,
      started_at: new Date().toISOString(),
    });
    broker.postCallback({ handle, nonce, result: { terminal_status: "in_review" } });

    const events: Record<string, unknown>[] = [];
    const result = await runReapLoop({
      broker,
      workspaceRoots: [wsRoot],
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      githubToken: GITHUB_TOKEN,
      emit: (e) => events.push(e),
    });

    expect(result).toEqual({ dispatched: 0, failed: 1 });

    const notFoundEvent = events.find((e) => e.type === "reap_workspace_not_found");
    expect(notFoundEvent).toBeDefined();
    expect(notFoundEvent!.task_id).toBe(TASK_ID);
    expect(notFoundEvent!.feature_id).toBe(FEATURE_ID);

    // Item nacked (stays in queue for retry)
    broker.reclaimExpired();
    const retry = await broker.listCompleted({ max: 1 });
    expect(retry).toHaveLength(1);
  });
});

