/**
 * Shared reap loop — drains completed executions from the broker,
 * routes by handle.kind, and dispatches side-effects.
 *
 * Called once per orchestrator cycle after the claim and review-fix
 * concerns have submitted their work. Any orchestrator can drain any
 * completion — dispatch is opportunistic, not pinned to the submitter.
 *
 * Routing:
 *   kind=impl       → dispatchExecutorResult (task YAML mutation)
 *   kind=review-fix → emit review_dispatch_complete event
 *
 * Error handling: individual dispatch errors are emitted as events and
 * the item is nacked (returned to the queue). Non-throwing.
 */

import { existsSync } from "node:fs";
import { execSync } from "node:child_process";
import type { CompletionBrokerPort } from "@workflow/runtime-abi";
import { dispatchExecutorResult } from "../side-effects/dispatch.js";
import { dispatchReviewResult, type ReviewResult } from "../side-effects/dispatch-review-result.js";
import { readTask, writeTask } from "../utils/task-yaml-io.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { tryReadTaskFromBranch } from "../task-branch-state.js";
import type { Task } from "../types/task.js";
import {
  resolveRepoGitUrl,
  resolveRepoBaseBranch,
} from "../config/workspace-config.js";
import { mutateTaskYaml } from "../side-effects/mutate-task-yaml.js";
import { buildGitEnv } from "../git-env.js";
import type { NotificationPort } from "../notifications/notification.port.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ReapLoopOptions {
  broker: CompletionBrokerPort;
  /** All workspace roots pulled this cycle — used to locate the task YAML. */
  workspaceRoots: string[];
  /** Visibility-lock duration for peek-and-lock. Default: 30 000 ms. */
  lockMs?: number;
  /** Max completions to drain per call. Default: 10. */
  max?: number;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  githubToken: string;
  emit: (event: Record<string, unknown>) => void;
  /**
   * Shared set of `featureId:taskId` keys for in-flight rebase executors.
   * When a rebase completion is acked, its key is removed so the next PR poll
   * cycle can dispatch a new rebase if the conflict persists.
   */
  rebaseInFlight?: Set<string>;
  /** Notification port — passed to dispatch functions for task-level notifications. */
  notifier?: NotificationPort | null;
}

export interface ReapLoopResult {
  /** Completions successfully dispatched and acked. */
  dispatched: number;
  /** Completions that failed to dispatch (nacked, will be retried). */
  failed: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Find the workspace root whose tasks directory contains the given task YAML.
 * Returns undefined if the task is not found in any pulled workspace.
 *
 * Checks local FS first (origin/main snapshot). Falls back to the task branch
 * on origin for tasks that were added directly to a feature branch without a
 * PR to main (e.g. a task whose YAML lives only on feature/<featureId>-<taskId>).
 */
function findWorkspaceRoot(
  workspaceRoots: string[],
  featureId: string,
  taskId: string,
): string | undefined {
  const relPath = taskYamlRelPath(featureId, taskId);
  const branch = taskBranchName(featureId, taskId);
  for (const root of workspaceRoots) {
    try {
      if (existsSync(taskYamlAbsPath(root, featureId, taskId))) return root;
    } catch {
      // ignore fs errors
    }
    // Task not on local FS — check task branch on origin
    if (tryReadTaskFromBranch(root, branch, relPath)) return root;
  }
  return undefined;
}

/**
 * Read a task YAML, falling back to the task branch on origin when the file
 * is absent from the local FS (origin/main snapshot).
 */
function readTaskAny(workspaceRoot: string, featureId: string, taskId: string): Task {
  if (existsSync(taskYamlAbsPath(workspaceRoot, featureId, taskId))) {
    return readTask(workspaceRoot, featureId, taskId);
  }
  const relPath = taskYamlRelPath(featureId, taskId);
  const branch = taskBranchName(featureId, taskId);
  const fromBranch = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
  if (fromBranch) return fromBranch;
  throw new Error(`task ${featureId}/${taskId} not found on local FS or origin/${branch}`);
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Drain the broker completion queue once and dispatch each completion.
 * Non-throwing: all errors are emitted and nacked.
 */
export async function runReapLoop(opts: ReapLoopOptions): Promise<ReapLoopResult> {
  const {
    broker,
    workspaceRoots,
    lockMs = 30_000,
    max = 10,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    githubToken,
    emit,
    rebaseInFlight,
    notifier,
  } = opts;

  const completions = await broker.listCompleted({ max, lockMs });
  let dispatched = 0;
  let failed = 0;

  for (const completion of completions) {
    const { handle, result, metadata } = completion;
    const { kind, task_id: taskId, feature_id: featureId } = metadata;

    try {
      const workspaceRoot = findWorkspaceRoot(workspaceRoots, featureId, taskId);
      if (!workspaceRoot) {
        emit({
          type: "reap_workspace_not_found",
          handle,
          task_id: taskId,
          feature_id: featureId,
        });
        await broker.nack(handle);
        failed++;
        continue;
      }

      const taskBranch = `feature/${featureId}-${taskId}`;

      if (kind === "impl") {
        const task = readTaskAny(workspaceRoot, featureId, taskId);
        const taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
        const taskBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);

        await dispatchExecutorResult({
          result,
          workspaceRoot,
          featureId,
          taskId,
          taskBranch,
          taskTitle: task.title,
          taskRepoUrl,
          taskBaseBranch,
          githubToken,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          notifier,
          emit,
        });

        emit({
          type: "executor_result",
          task_id: taskId,
          feature_id: featureId,
          terminal_status: result.terminal_status,
        });
      } else if (kind === "review-fix") {
        emit({
          type: "review_dispatch_complete",
          task_id: taskId,
          feature_id: featureId,
          subkind: metadata.subkind ?? "respond",
          outcome: result.terminal_status,
          handle,
        });
      } else if (kind === "review") {
        const reviewTask = readTaskAny(workspaceRoot, featureId, taskId);
        await dispatchReviewResult({
          result: result as unknown as ReviewResult,
          workspaceRoot,
          featureId,
          taskId,
          taskTitle: reviewTask.title,
          prUrl: reviewTask.pr?.url ?? undefined,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          notifier,
          emit,
        });
      } else if (kind === "rebase") {
        if (result.terminal_status === "blocked") {
          const mutErr = mutateTaskYaml({
            workspaceRoot,
            featureId,
            taskId,
            taskBranch,
            result: {
              terminal_status: "blocked",
              blocked_reason: result.blocked_reason ?? "pr_conflict",
            },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (mutErr) {
            emit({
              type: "rebase_blocked_write_failed",
              task_id: taskId,
              feature_id: featureId,
              details: mutErr,
            });
          }
        } else if (result.terminal_status === "in_review") {
          // Rebase succeeded — write conflict_state: resolved to the task YAML.
          const env = buildGitEnv(sshKeyPath, {
            email: gitAuthorEmail,
            name: gitAuthorName ?? gitAuthorEmail,
          });
          execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
          execSync(
            `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
            { env, stdio: "pipe" },
          );
          const rebasedTask = readTask(workspaceRoot, featureId, taskId);
          rebasedTask.conflict_state = "resolved";
          rebasedTask.execution.last_updated_by = gitAuthorEmail;
          rebasedTask.execution.last_updated_at = new Date().toISOString();
          rebasedTask.log.push({
            action: "rebase_completed",
            by: gitAuthorEmail,
            at: new Date().toISOString(),
            note: "Rebase succeeded — conflict_state resolved. Reviewer cycle can resume.",
          });
          writeTask(workspaceRoot, featureId, rebasedTask);
          const relPath = taskYamlRelPath(featureId, taskId);
          execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
          execSync(
            `git -C "${workspaceRoot}" commit -m "chore(${taskId}): conflict_state → resolved"`,
            { env, stdio: "pipe" },
          );
          execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, { env, stdio: "pipe" });
        }
      }

      await broker.ack(handle);
      if (kind === "rebase" && rebaseInFlight) {
        rebaseInFlight.delete(`${featureId}:${taskId}`);
      }
      emit({
        type: "reap_acked",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        terminal_status: result.terminal_status,
      });
      dispatched++;
    } catch (e) {
      emit({
        type: "reap_dispatch_error",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        details: String(e),
      });
      if (kind === "rebase" && rebaseInFlight) {
        rebaseInFlight.delete(`${featureId}:${taskId}`);
      }
      try {
        await broker.nack(handle);
      } catch {
        // best-effort nack
      }
      failed++;
    }
  }

  return { dispatched, failed };
}

