 */
function readTaskAny(workspaceRoot: string, featureId: string, taskId: string): Task {
  if (existsSync(taskYamlAbsPath(workspaceRoot, featureId, taskId))) {
    return readTask(workspaceRoot, featureId, taskId);
  }
  const relPath = taskYamlRelPath(featureId, taskId);
  const branch = taskBranchName(featureId, taskId);
  const fromBranch = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
  if (fromBranch) return fromBranch;
  throw new Error(`task ${featureId}/${taskId} not found on local FS or origin/${branch}`);
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Drain the broker completion queue once and dispatch each completion.
 * Non-throwing: all errors are emitted and nacked.
 */
export async function runReapLoop(opts: ReapLoopOptions): Promise<ReapLoopResult> {
  const {
    broker,
    workspaceRoots,
    lockMs = 30_000,
    max = 10,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    githubToken,
    emit,
    rebaseInFlight,
    notifier,
  } = opts;

  const completions = await broker.listCompleted({ max, lockMs });
  let dispatched = 0;
  let failed = 0;

  for (const completion of completions) {
    const { handle, result, metadata } = completion;
    const { kind, task_id: taskId, feature_id: featureId } = metadata;

    try {
      const workspaceRoot = findWorkspaceRoot(workspaceRoots, featureId, taskId);
      if (!workspaceRoot) {
        emit({
          type: "reap_workspace_not_found",
          handle,
          task_id: taskId,
          feature_id: featureId,
        });
        await broker.nack(handle);
        failed++;
        continue;
      }

      const taskBranch = `feature/${featureId}-${taskId}`;

      if (kind === "impl") {
        const task = readTaskAny(workspaceRoot, featureId, taskId);
        const taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
        const taskBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);

        await dispatchExecutorResult({
          result,
          workspaceRoot,
          featureId,
          taskId,
          taskBranch,
          taskTitle: task.title,
          taskRepoUrl,
          taskBaseBranch,
          githubToken,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          notifier,
          emit,
        });

        emit({
          type: "executor_result",
          task_id: taskId,
          feature_id: featureId,
          terminal_status: result.terminal_status,
        });
      } else if (kind === "review-fix") {
        emit({
          type: "review_dispatch_complete",
          task_id: taskId,
          feature_id: featureId,
          subkind: metadata.subkind ?? "respond",
          outcome: result.terminal_status,
          handle,
        });
      } else if (kind === "review") {
        const reviewTask = readTaskAny(workspaceRoot, featureId, taskId);
        await dispatchReviewResult({
          result: result as unknown as ReviewResult,
          workspaceRoot,
          featureId,
          taskId,
          taskTitle: reviewTask.title,
          prUrl: reviewTask.pr?.url ?? undefined,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          notifier,
          emit,
        });
      } else if (kind === "rebase") {
        if (result.terminal_status === "blocked") {
          const mutErr = mutateTaskYaml({
            workspaceRoot,
            featureId,
            taskId,
            taskBranch,
            result: {
              terminal_status: "blocked",
              blocked_reason: result.blocked_reason ?? "pr_conflict",
            },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          if (mutErr) {
            emit({
              type: "rebase_blocked_write_failed",
              task_id: taskId,
              feature_id: featureId,
              details: mutErr,
            });
          }
        } else if (result.terminal_status === "in_review") {
          // Rebase succeeded — write conflict_state: resolved to the task YAML.
          const env = buildGitEnv(sshKeyPath, {
            email: gitAuthorEmail,
            name: gitAuthorName ?? gitAuthorEmail,
          });
          execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
          execSync(
            `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
            { env, stdio: "pipe" },
          );
          const rebasedTask = readTask(workspaceRoot, featureId, taskId);
          rebasedTask.conflict_state = "resolved";
          rebasedTask.execution.last_updated_by = gitAuthorEmail;
          rebasedTask.execution.last_updated_at = new Date().toISOString();
          rebasedTask.log.push({
            action: "rebase_completed",
            by: gitAuthorEmail,
            at: new Date().toISOString(),
            note: "Rebase succeeded — conflict_state resolved. Reviewer cycle can resume.",
          });
          writeTask(workspaceRoot, featureId, rebasedTask);
          const relPath = taskYamlRelPath(featureId, taskId);
          execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
          execSync(
            `git -C "${workspaceRoot}" commit -m "chore(${taskId}): conflict_state → resolved"`,
            { env, stdio: "pipe" },
          );
          execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, { env, stdio: "pipe" });
        }
      }

      await broker.ack(handle);
      if (kind === "rebase" && rebaseInFlight) {
        rebaseInFlight.delete(`${featureId}:${taskId}`);
      }
      emit({
        type: "reap_acked",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        terminal_status: result.terminal_status,
      });
      dispatched++;
    } catch (e) {
      emit({
        type: "reap_dispatch_error",
        handle,
        task_id: taskId,
        feature_id: featureId,
        kind,
        details: String(e),
      });
      if (kind === "rebase" && rebaseInFlight) {
        rebaseInFlight.delete(`${featureId}:${taskId}`);
      }
      try {
        await broker.nack(handle);
      } catch {
        // best-effort nack
      }
      failed++;
    }
  }

  return { dispatched, failed };
}

