import type { NotificationPort } from "../src/notifications/notification.port.js";

describe("handleEscalation — notifier injection", () => {
  it("calls notifier.postTaskMessage instead of Slack webhook when notifier is provided", async () => {
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const mockFetch = vi.fn();
    vi.stubGlobal("fetch", mockFetch);

    const notifierCalls: Array<{ featureId: string; taskId: string; trigger: string }> = [];
    const notifier: NotificationPort = {
      postTaskMessage: async (fid, tid, trigger) => {
        notifierCalls.push({ featureId: fid, taskId: tid, trigger });
      },
      closeTaskThread: async () => {},
      postFeatureMessage: async () => {},
      closeFeatureThread: async () => {},
    };

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: task.title,
      prUrl: task.pr.url,
      notes: "Reviewer confidence too low.",
      gitAuthorEmail: "bot@test.com",
      notifier,
      emit: (e) => events.push(e),
    });

    // Notifier was called with the task_review_changed trigger
    expect(notifierCalls).toHaveLength(1);
    expect(notifierCalls[0].trigger).toBe("task_review_changed");
    expect(notifierCalls[0].featureId).toBe(FEATURE_ID);
    expect(notifierCalls[0].taskId).toBe(TASK_ID);

    // Webhook fetch was NOT called (notifier takes priority)
    expect(mockFetch).not.toHaveBeenCalled();

    // Task still escalated and YAML mutated
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(false);
  });

  it("emits escalation_slack_failed when notifier throws but still mutates YAML", async () => {
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const failingNotifier: NotificationPort = {
      postTaskMessage: async () => { throw new Error("Slack unavailable"); },
      closeTaskThread: async () => {},
      postFeatureMessage: async () => {},
      closeFeatureThread: async () => {},
    };

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: task.title,
      notes: "Reviewer confidence too low.",
      gitAuthorEmail: "bot@test.com",
      notifier: failingNotifier,
      emit: (e) => events.push(e),
    });

    // Escalation failure emitted
    expect(events.some((e) => e.type === "escalation_slack_failed")).toBe(true);
    // Task still escalated (notification failure is non-blocking)
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
  });
});

