/**
 * Tests for T6 — escalation handler.
 *   1. handleEscalation with Slack configured → posts to webhook, mutates YAML, emits task_escalated
 *   2. handleEscalation with Slack URL absent → skips webhook, mutates YAML, emits task_escalated
 *   3. handleEscalation when Slack POST fails → emits escalation_slack_failed, continues to mutate
 *   4. handleEscalation when task YAML mutation fails → emits escalation_mutate_failed
 *   5. postEscalationSlack payload shape
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify, parse as yamlParse } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "esc-feature";
const TASK_ID = "T6";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const ORIGINAL_SLACK_URL = process.env["SLACK_WEBHOOK_URL"];

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Escalation handler",
    repo: "workflow",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
    pr: { url: "https://github.com/org/repo/pull/42", status: "open" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function makePushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

// ── Temp workspace helpers ─────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(task: Task): string {
  const wsDir = mkdtempSync(join(tmpdir(), "escalation-"));
  tmpDirs.push(wsDir);

  const tasksDir = join(wsDir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");

  return wsDir;
}

// ── Setup / teardown ──────────────────────────────────────────────────────────

beforeEach(() => {
  delete process.env["SLACK_WEBHOOK_URL"];
});

afterEach(() => {
  if (ORIGINAL_SLACK_URL !== undefined) {
    process.env["SLACK_WEBHOOK_URL"] = ORIGINAL_SLACK_URL;
  } else {
    delete process.env["SLACK_WEBHOOK_URL"];
  }
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
  vi.unstubAllGlobals();
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("handleEscalation — Slack present", () => {
  it("posts to Slack webhook and emits task_escalated on success", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/TEST";
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const mockFetch = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => "ok",
    });
    vi.stubGlobal("fetch", mockFetch);

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: task.title,
      prUrl: task.pr.url,
      notes: "Reviewer confidence too low to auto-approve.",
      reviewUrl: "https://github.com/org/repo/pull/42#review-1",
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    expect(url).toBe("https://hooks.slack.com/services/TEST");
    expect(init.method).toBe("POST");
    const body = JSON.parse(init.body as string) as { text: string; blocks: unknown[] };
    expect(body.text).toContain("T6");
    expect(body.blocks).toBeDefined();

    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(false);
  });

  it("emits escalation_slack_failed when Slack POST returns non-ok but still mutates YAML", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/BAD";
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const mockFetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 500,
      text: async () => "Internal Server Error",
    });
    vi.stubGlobal("fetch", mockFetch);

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: task.title,
      prUrl: task.pr.url,
      notes: "CI failed 3 times.",
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "escalation_slack_failed")).toBe(true);
    // still continues to mutate and escalate
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
  });

  it("includes feature ID, task ID, PR URL, and reason in Slack payload", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/TEST";

    const mockFetch = vi.fn().mockResolvedValue({ ok: true, text: async () => "ok" });
    vi.stubGlobal("fetch", mockFetch);

    const { postEscalationSlack } = await import("../src/side-effects/escalation-handler.js");

    await postEscalationSlack(
      {
        workspaceRoot: "/fake",
        featureId: FEATURE_ID,
        taskId: TASK_ID,
        taskTitle: "Escalation handler",
        prUrl: "https://github.com/org/repo/pull/42",
        notes: "Confidence 0.3 — too uncertain.",
        reviewUrl: "https://github.com/org/repo/pull/42#review-99",
        gitAuthorEmail: "bot@test.com",
        emit: vi.fn(),
      },
      "https://hooks.slack.com/services/TEST",
    );

    const body = JSON.parse((mockFetch.mock.calls[0] as [string, RequestInit])[1].body as string) as {
      text: string;
      blocks: Array<{ type: string; fields?: Array<{ text: string }> }>;
    };

    expect(body.text).toContain(TASK_ID);
    const sectionFields = body.blocks.flatMap((b) => b.fields ?? []).map((f) => f.text);
    expect(sectionFields.some((f) => f.includes(FEATURE_ID))).toBe(true);
    expect(sectionFields.some((f) => f.includes("pull/42"))).toBe(true);
  });
});

describe("handleEscalation — Slack absent", () => {
  it("skips Slack and emits escalation_slack_skipped", async () => {
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const mockFetch = vi.fn();
    vi.stubGlobal("fetch", mockFetch);

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: task.title,
      prUrl: task.pr.url,
      notes: "Reviewer escalated.",
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(mockFetch).not.toHaveBeenCalled();
    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(true);
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
  });

  it("mutates task YAML to blocked with correct blocked_reason and blocked_suggestion", async () => {
    const task = makeTask();
    const wsDir = makeWorkspace(task);

    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spawnSync).mockReturnValue(makePushSuccess());

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");

    await handleEscalation({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      notes: "Low confidence: 0.3",
      gitAuthorEmail: "bot@test.com",
      emit: vi.fn(),
    });

    const yamlPath = join(wsDir, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`);
    const mutated = yamlParse(readFileSync(yamlPath, "utf-8")) as Task;

    expect(mutated.status).toBe("blocked");
    expect(mutated.blocked_reason).toBe("Low confidence: 0.3");
    expect(mutated.blocked_suggestion).toContain("Human review required");
    expect(mutated.log.at(-1)?.action).toBe("reviewer_complete");
  });

  it("emits escalation_mutate_failed when git operations fail", async () => {
    const { execSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => {
      throw new Error("git not available");
    });

    const { handleEscalation } = await import("../src/side-effects/escalation-handler.js");
    const events: Record<string, unknown>[] = [];

    await handleEscalation({
      workspaceRoot: "/nonexistent",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      notes: "Something went wrong.",
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "escalation_slack_skipped")).toBe(true);
    expect(events.some((e) => e.type === "escalation_mutate_failed")).toBe(true);
    expect(events.some((e) => e.type === "task_escalated")).toBe(false);
  });
});

