// ── Notifier injection on done ────────────────────────────────────────────────

// Note: notifier "done" tests removed.
// dispatchReviewResult no longer calls the notifier in the passed branch — the
// task is not yet done at this point. Notifier integration belongs in
// handleMergedPrs (where the mark-done write actually happens). That is not
// wired up in this PR and is a separate follow-up.

// ── dispatchReviewResult — unknown status (review_blocked retry) ──────────────

describe("dispatchReviewResult — unknown status: review_blocked retry", () => {
  beforeEach(() => {
    delete process.env["MAX_REVIEW_INCOMPLETES"];
  });

  it("first incomplete: writes review_blocked log entry and emits review_blocked_logged with attempt:1", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review", log: [] });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "blocked" as never, verdict: undefined as never, confidence: 0, notes: "" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_incomplete")).toBe(true);
    const loggedEvent = events.find((e) => e.type === "review_blocked_logged");
    expect(loggedEvent).toBeDefined();
    expect(loggedEvent?.attempt).toBe(1);
